  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines[0].discountPercent, undefined);
});

test('lineDiscount calculates discount correctly', () => {
  const line = {
    qty: 10,
    unitPrice: 9500,
    discountPercent: 10,
  };

  const discount = lineDiscount(line);
  assert.strictEqual(discount, 9500);
});

test('lineDiscount returns 0 for no discount', () => {
  const line = {
    qty: 10,
    unitPrice: 9500,
  };

  const discount = lineDiscount(line);
  assert.strictEqual(discount, 0);
});

test('lineDiscount with decimal percentage', () => {
  const line = {
    qty: 100,
    unitPrice: 37,
    discountPercent: 12.5,
  };

  const discount = lineDiscount(line);
  const total = 100 * 37;
  const expectedDiscount = Math.round((total * 12.5) / 100);
  assert.strictEqual(discount, expectedDiscount);
});

test('lineDiscount clamps to 0', () => {
  const line = {
    qty: 1,
    unitPrice: 10,
    discountPercent: 200,
  };

  const discount = lineDiscount(line);
  assert.strictEqual(discount >= 0, true);
});

test('invoiceTotals returns discount and total with no discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  assert.strictEqual(totals.discount, 0);
  assert.strictEqual(totals.total, 47500);
  assert.strictEqual(totals.subtotal, 47500);
});

test('invoiceTotals calculates discount correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  const subtotal = 10 * 9500;
  const expectedDiscount = (subtotal * 10) / 100;
  assert.strictEqual(totals.subtotal, 95000);
  assert.strictEqual(totals.discount, expectedDiscount);
  assert.strictEqual(totals.total, subtotal - expectedDiscount);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 5 },
    ],
  });
  assert.strictEqual(result.ok, true);

  const totals = invoiceTotals(result.value);
  const devTotal = 10 * 9500;
  const desTotal = 5 * 8500;
  const subtotal = devTotal + desTotal;
  const devDiscount = (devTotal * 10) / 100;
  const desDiscount = (desTotal * 5) / 100;
  const totalDiscount = devDiscount + desDiscount;

  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, totalDiscount);
  assert.strictEqual(totals.total, subtotal - totalDiscount);
});

test('invoiceTotals clamps total to 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 1,
        unitPrice: 50,
        vatRate: 21,
        discountPercent: 100,
      },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.total >= 0, true);
});

test('addLine accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 15 });

  assert.strictEqual(addResult.ok, true);
  assert.strictEqual(addResult.value.lines[1].discountPercent, 15);
});

test('addLine fails with DISCOUNT_INVALID for invalid discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 150 });

  assert.strictEqual(addResult.ok, false);
  assert.strictEqual(addResult.error, 'DISCOUNT_INVALID');
});

