  assert.notMatch(text, /Discount:/);
  assert.match(text, /Total: €475\.00/);
});

test('renderInvoiceText with mixed discount and non-discount lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });
  assert.strictEqual(result.ok, true);

  const text = renderInvoiceText(result.value);
  assert.match(text, /Development \(hour\) €95\.00 €950\.00 -€95\.00/);
  assert.match(text, /Design work \(hour\) €85\.00 €425\.00/);
  assert.match(text, /Subtotal: €1,375\.00/);
  assert.match(text, /Discount: -€95\.00/);
  assert.match(text, /Total: €1,280\.00/);
});
